//! The game (world) message table, generated from the GWPS reference. DO NOT EDIT BY HAND.
//!
//! Generated by `tools/gen-game-tables.py` from the sibling GWPS checkout
//! (`docs/adr/0005-gwps-reference-only.md`), revision d246a2a:
//!
//! ```text
//! code/OpenTyria/opcodes.h   names, counts and direction masks
//! code/OpenTyria/msgdefs.c   GAME_CMSG_FORMATS / GAME_SMSG_FORMATS (max_size), and the
//!                            per-message MsgField arrays (the field layout)
//! code/OpenTyria/msgpack.c   field widths, and the wire form of a counted field
//! ```
//!
//! Regenerate with `python tools/gen-game-tables.py`; verify with `--check`. The table is a
//! copied fact, not a design: a size disagreement with GWPS is what desynchronises the
//! stream, and the client itself reports nothing but error 007 (`docs/03-protocol.md`,
//! section 1).
//!
//! ## What `size` is
//!
//! [`Entry::size`] is the reference's `max_size`: a **maximum**, not the size the message
//! occupies on the wire. The reference computes it as the field sum with every counted
//! field at full capacity behind a four-byte count -- that is, the size of the struct it
//! unpacks into, not of the packet.
//!
//! A counted field on the wire -- `TYPE_STRING_16`, `TYPE_ARRAY_8`, `TYPE_ARRAY_16`,
//! `TYPE_ARRAY_32` -- is a **u16 count followed by exactly that many units and nothing
//! else**: no padding out to the capacity the field layout declares, and no four-byte
//! count (`msgpack.c`, `pack_helper` and `unpack_helper`). This is a measured fact in this
//! project, recorded in `docs/03-protocol.md` section 1 and section 6: a real client sends
//! `AUTH_CMSG_SEND_COMPUTER_INFO` as 42 bytes where the auth table declares 138.
//!
//! The consequences for framing code, which are the reason this paragraph is here:
//!
//! * `size` is an upper bound, two bytes per counted field looser than the largest message
//!   the packer can produce. It is never "read exactly this many bytes".
//! * A body can only be consumed structurally, field by field, following the counted
//!   lengths as they are read. No header fixes the length of a message with a counted
//!   field, and nothing on the wire delimits the body.
//! * [`declared_max_size`] recomputes `size` from a row's own field layout, so a wrong
//!   number cannot survive a test. Every row reproduces exactly except the two listed in
//!   [`SIZE_NOT_RECOMPUTABLE_FROM_LAYOUT`].
//!
//! ## Two things the reference does not answer
//!
//! 342 of the 682 indices below have no name in `opcodes.h`; they carry the reference's
//! size and stay `None`-named, so an unexpected-but-real header is still recognised instead
//! of being mistaken for a malformed message. And 1 header carries two names in `opcodes.h`;
//! see [`AMBIGUOUS_NAME_HEADERS`] and the alias constant beside the name it collides with.

/// `GAME_CMSG_MASK`: set on client-to-server headers, and therefore also the direction bit.
pub const GAME_CMSG_MASK: u16 = 0x8000;
/// `GAME_SMSG_MASK`: server-to-client headers carry no direction bit.
pub const GAME_SMSG_MASK: u16 = 0x0000;

/// Number of client-to-server game headers (`GAME_CMSG_COUNT`).
pub const GAME_CMSG_COUNT: usize = 194;
/// Number of server-to-client game headers (`GAME_SMSG_COUNT`).
pub const GAME_SMSG_COUNT: usize = 488;

/// A field kind, as `msgdefs.c` names it (`FieldType` in `msgdefs.h`).
///
/// The same kinds the auth table uses, and the same field data on the wire, but the counted
/// kinds are documented for what they are: a u16 count then that many units, no padding.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FieldKind {
    /// `TYPE_MSG_HEADER`: the u16 header, two bytes on the wire.
    MsgHeader,
    /// `TYPE_MSG_HEADER_GAME`: the header plus a zero u16, four bytes on the wire.
    /// Defined, packed and unpacked in the reference, but **no** row of either game format
    /// table uses it -- opt-in per message, and nothing is opted in. Kept here so a capture
    /// that shows one can be named.
    MsgHeaderGame,
    /// `TYPE_AGENT_ID`: a four-byte agent number.
    AgentId,
    /// `TYPE_FLOAT`.
    Float,
    /// `TYPE_VECT2`: two floats.
    Vect2,
    /// `TYPE_VECT3`: three floats.
    Vect3,
    /// `TYPE_BYTE`.
    Byte,
    /// `TYPE_WORD`.
    Word,
    /// `TYPE_DWORD`.
    Dword,
    /// `TYPE_BLOB`: `length` opaque bytes, no count prefix.
    Blob,
    /// `TYPE_STRING_16`: a u16 count then that many u16 units. `length` is the capacity,
    /// not the length on the wire.
    String16,
    /// `TYPE_ARRAY_8`: a u16 count then that many u8 units.
    Array8,
    /// `TYPE_ARRAY_16`: a u16 count then that many u16 units.
    Array16,
    /// `TYPE_ARRAY_32`: a u16 count then that many u32 units.
    Array32,
    /// `TYPE_NESTED_STRUCT`: a u8 count then that many repeats of the remaining fields.
    /// `length` is the maximum count.
    NestedStruct,
}

/// One field: its kind and, for the kinds that carry a count or a length, that number.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Field {
    pub kind: FieldKind,
    /// `field.length` in the reference: the unit capacity, the blob size, or 0 when unused.
    pub length: u16,
}

impl Field {
    /// Bytes this field occupies on the wire when a counted field carries `count` units, or
    /// `None` for [`FieldKind::NestedStruct`], whose size depends on the repeats it carries.
    ///
    /// `count` is ignored by every kind that has no count of its own. A counted field is a
    /// two-byte count then `count` units and nothing else, so even at capacity it is two
    /// bytes smaller than the field's share of [`declared_max_size`]: the declared maximum
    /// bounds the wire, it is not the wire.
    pub fn wire_size(&self, count: u16) -> Option<usize> {
        let n = self.length as usize;
        let count = count as usize;
        match self.kind {
            FieldKind::MsgHeader => Some(2),
            FieldKind::MsgHeaderGame => Some(4),
            FieldKind::AgentId | FieldKind::Float | FieldKind::Dword => Some(4),
            FieldKind::Vect2 => Some(8),
            FieldKind::Vect3 => Some(12),
            FieldKind::Byte => Some(1),
            FieldKind::Word => Some(2),
            FieldKind::Blob => Some(n),
            // The capacity is only a maximum; the count the body carries decides the wire,
            // and the reference rejects a count above the capacity (`pack_helper`).
            FieldKind::String16 | FieldKind::Array16 => Some(2 + count * 2),
            FieldKind::Array8 => Some(2 + count),
            FieldKind::Array32 => Some(2 + count * 4),
            FieldKind::NestedStruct => None,
        }
    }
}

/// The value `msgdefs.c` derives a row's `max_size` from: the reference's own arithmetic,
/// with every counted field at full capacity behind a four-byte count.
///
/// This is *not* a wire size -- see the module documentation. It exists so the table can
/// check itself: for every row, `declared_max_size(entry.fields) == entry.size`, with the
/// two exceptions in [`SIZE_NOT_RECOMPUTABLE_FROM_LAYOUT`].
pub fn declared_max_size(fields: &[Field]) -> usize {
    let mut total = 0;
    for (position, field) in fields.iter().enumerate() {
        let n = field.length as usize;
        total += match field.kind {
            FieldKind::MsgHeader => 2,
            FieldKind::MsgHeaderGame => 4,
            FieldKind::AgentId | FieldKind::Float | FieldKind::Dword => 4,
            FieldKind::Vect2 => 8,
            FieldKind::Vect3 => 12,
            FieldKind::Byte => 1,
            FieldKind::Word => 2,
            FieldKind::Blob => n,
            FieldKind::String16 | FieldKind::Array16 => 4 + n * 2,
            FieldKind::Array8 => 4 + n,
            FieldKind::Array32 => 4 + n * 4,
            FieldKind::NestedStruct => 4 + n * declared_max_size(&fields[position + 1..]),
        };
        if field.kind == FieldKind::NestedStruct {
            break;
        }
    }
    total
}

/// One row of the game message table.
#[derive(Debug, Clone, Copy)]
pub struct Entry {
    /// The wire value, mask included: `0x8000 | index` or `0x0000 | index`.
    ///
    /// The same value means a different message in the auth family, which is why every
    /// lookup below also takes the direction.
    pub header: u16,
    /// The index GWPS uses to address its format array (`header & 0x7FFF`).
    pub index: u16,
    /// The declared maximum, `max_size` in `msgdefs.c` -- **not** the size on the wire.
    ///
    /// Two bytes per counted field more than the packer can ever produce. See the module
    /// documentation; a framer must not read it as a body length.
    pub size: usize,
    /// The GWPS name, when `opcodes.h` gives this index one; `None` for the 342 indices it
    /// does not name.
    pub name: Option<&'static str>,
    /// Whether the header is client-to-server (`0x8000` set).
    pub from_client: bool,
    /// The fields the message is made of, in wire order.
    pub fields: &'static [Field],
}

